config.assertProductionSecrets()
const app=express()
if(config.trustProxy)app.set('trust proxy',1)
app.disable('x-powered-by')
app.use((req,res,next)=>{res.set({'X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'strict-origin-when-cross-origin','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self' https://tile.openstreetmap.org; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",'X-Robots-Tag':'noai, noimageai','X-Karnata-Origin':PUBLIC_DATA_ATTRIBUTION.canonicalUrl,'Cross-Origin-Resource-Policy':'same-site'});next()})
app.use(express.json({limit:'12mb'}))

const allowedOrigins=new Set([config.appOrigin])
const publicMessageOrigins=new Set([config.appOrigin,...config.publicMessageOrigins])
app.use('/api/public/messages',(req,res,next)=>{const origin=req.get('origin');if(origin&&!publicMessageOrigins.has(origin))return res.status(403).json({error:'Origin is not allowed.'});if(origin)res.set({'Access-Control-Allow-Origin':origin,Vary:'Origin','Access-Control-Allow-Headers':'Content-Type','Access-Control-Allow-Methods':'POST, OPTIONS'});if(req.method==='OPTIONS')return res.status(204).end();next()})
app.use('/api',(req,res,next)=>{if(req.path==='/public/messages'||['GET','HEAD','OPTIONS'].includes(req.method))return next();const origin=req.get('origin');if(origin&&!allowedOrigins.has(origin))return res.status(403).json({error:'Origin is not allowed.'});next()})

const attempts=new Map()
const rateLimit=(bucket,max,windowMs)=>(req,res,next)=>{const key=`${bucket}:${req.ip}`;const now=Date.now();const entry=attempts.get(key);if(!entry||entry.until<now){attempts.set(key,{count:1,until:now+windowMs});return next()}if(entry.count>=max)return res.status(429).json({error:'Too many attempts. Please try again later.'});entry.count+=1;next()}
const cookies=req=>Object.fromEntries((req.headers.cookie||'').split(';').map(value=>value.trim().split(/=(.*)/s)).filter(parts=>parts[0]).map(([key,value])=>[decodeURIComponent(key),decodeURIComponent(value||'')]))
const clean=(value,max=255)=>typeof value==='string'?value.trim().slice(0,max):''
const email=value=>clean(value,254).toLowerCase()
const safeJson=value=>{try{return typeof value==='string'?JSON.parse(value):value}catch{return null}}
const safeUrl=value=>{const text=clean(value,1000);if(!text)return null;try{const url=new URL(text);return ['http:','https:'].includes(url.protocol)?url.href:null}catch{return null}}
const rolesFor=async(db,userId)=>(await db.query('SELECT role FROM user_roles WHERE user_id=?',[userId])).map(row=>row.role)
const publicUser=(row,roles,karma=0)=>({id:row.id,email:row.email,displayName:row.display_name,displayNameKn:row.display_name_kn,preferredLocale:row.preferred_locale,profession:row.profession,professionDetails:row.profession_details,affiliationType:row.affiliation_type,institutionName:row.institution_name,institutionUrl:row.institution_url,publicBio:row.public_bio,accountStatus:row.account_status,verifiedBadge:Boolean(row.verified_badge),roles,canExport:row.account_status==='approved'&&roles.some(role=>['exporter','administrator'].includes(role)),karma:Number(karma||0)})
const audit=async(db,actor,action,entityType,entityId,metadata={})=>db.query('INSERT INTO audit_log (id,actor_user_id,action,entity_type,entity_id,metadata_json) VALUES (?,?,?,?,?,?)',[randomUUID(),actor||null,action,entityType,entityId||null,JSON.stringify(metadata)])
const notify=async(db,userId,kind,titleEn,titleKn,messageEn,messageKn,entityType=null,entityId=null)=>db.query('INSERT INTO community_notifications (id,user_id,kind,title_en,title_kn,message_en,message_kn,entity_type,entity_id) VALUES (?,?,?,?,?,?,?,?,?)',[randomUUID(),userId,kind,titleEn,titleKn,messageEn,messageKn,entityType,entityId])
const normalizeImportRows=rows=>Array.isArray(rows)?rows.slice(0,500).filter(row=>row&&typeof row==='object'&&!Array.isArray(row)).map(row=>Object.fromEntries(Object.entries(row).slice(0,80).map(([key,value])=>[clean(key,120),clean(value==null?'':String(value),4000)]).filter(([key])=>key))):[]

async function loadSession(req,res,next){
  const token=cookies(req).kha_session;if(!token)return next()
  const rows=await pool.query(`SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>UTC_TIMESTAMP(3) LIMIT 1`,[sha256(token)])
  if(!rows.length){res.clearCookie('kha_session',{path:'/'});return next()}
  req.user=rows[0];req.roles=await rolesFor(pool,rows[0].id);next()
}
app.use('/api',loadSession)
const requireUser=(req,res,next)=>req.user?next():res.status(401).json({error:'Sign in is required.'})
const requireApproved=(req,res,next)=>req.user?.account_status==='approved'?next():res.status(403).json({error:'Sanchaya approval is required before contributing.'})
const requireRole=(...roles)=>(req,res,next)=>roles.some(role=>req.roles?.includes(role))?next():res.status(403).json({error:'This action requires an appointed role.'})
const datasetIssues=value=>validateAtlas(value).filter(issue=>issue.severity==='error')

app.get('/api/health',async(req,res)=>{await pool.query('SELECT 1');res.json({ok:true,service:'Karnataka Historical Atlas community API'})})
app.post('/api/public/messages',rateLimit('public-message',10,60*60*1000),async(req,res)=>{
  const body=req.body||{};if(clean(body.website,200))return res.status(400).json({error:'Message could not be accepted.'})
  const senderEmail=email(body.email),subject=clean(body.subject,255),message=clean(body.message,10000),category=['question','correction','source','technical','collaboration','other'].includes(body.category)?body.category:'other'
  if(senderEmail&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(senderEmail))return res.status(400).json({error:'Enter a valid email address or leave it blank.'})
  if(!subject||message.length<10||body.consent!==true)return res.status(400).json({error:'A subject, message of at least 10 characters and consent are required.'})
  const id=randomUUID(),referenceCode=`KHA-${new Date().getUTCFullYear()}-${id.slice(0,8).toUpperCase()}`,sourceDeployment=body.sourceDeployment==='github-pages'?'github-pages':'live'
  await transaction(async db=>{await db.query(`INSERT INTO portal_messages (id,reference_code,user_id,sender_name,sender_email,category,subject,message,locale,source_deployment,page_url,record_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,[id,referenceCode,req.user?.id||null,clean(body.name,160)||req.user?.display_name||null,senderEmail||req.user?.email||null,category,subject,message,body.locale==='en'?'en':'kn',sourceDeployment,safeUrl(body.pageUrl),clean(body.recordId,191)||null]);await audit(db,req.user?.id||null,'portal-message.created','portal-message',id,{referenceCode,category,sourceDeployment})})
  sendPortalNotifications(`Karnataka Historical Atlas\n${referenceCode} · ${category}\n${subject}\n${config.appOrigin}/#admin`,pool,config).catch(error=>console.error(error.message))
  res.status(201).json({ok:true,referenceCode})
})
app.get('/api/dataset',rateLimit('public-dataset',180,60*60*1000),async(req,res)=>{
  const latest=await latestDataset(pool)
  if(!latest)return res.status(503).set('Cache-Control','no-store').json({error:'The MariaDB atlas dataset has not been initialized.'})
  const publicPayload=publicDataset(latest.dataset)
  publicPayload.meta={...publicPayload.meta,attribution:PUBLIC_DATA_ATTRIBUTION}
  const payloadSha256=sha256(JSON.stringify(publicPayload))
  if(req.get('if-none-match')===`"${payloadSha256}"`)return res.status(304).end()
  const attribution={...PUBLIC_DATA_ATTRIBUTION,payloadSha256}
  const dataset={...publicPayload,meta:{...publicPayload.meta,attribution}}
  res.set({'Cache-Control':'no-store',ETag:`"${payloadSha256}"`,'X-Karnata-Payload-SHA256':payloadSha256}).json({...latest,payloadSha256,attribution,dataset})
})

app.post('/api/auth/register',rateLimit('register',8,60*60*1000),async(req,res)=>{
  const body=req.body||{};const userEmail=email(body.email);const displayName=clean(body.displayName,160);const profession=clean(body.profession,80)
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userEmail)||!displayName||!profession)return res.status(400).json({error:'A valid email, name and profession are required.'})
  if(typeof body.password!=='string'||body.password.length<12||body.password.length>200)return res.status(400).json({error:'Password must contain 12–200 characters.'})
  if(body.acceptTerms!==true||body.acceptPrivacy!==true)return res.status(400).json({error:'Terms and privacy consent are required.'})
  const passwordHash=await hashPassword(body.password);const id=randomUUID();const now=new Date()
  try{await transaction(async db=>{await db.query(`INSERT INTO users (id,email,password_hash,display_name,display_name_kn,preferred_locale,profession,profession_details,affiliation_type,institution_name,institution_url,public_bio,terms_accepted_at,privacy_accepted_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[id,userEmail,passwordHash,displayName,clean(body.displayNameKn,160)||null,body.preferredLocale==='en'?'en':'kn',profession,clean(body.professionDetails)||null,['school','college','university','research-institute','museum','government','nonprofit','other'].includes(body.affiliationType)?body.affiliationType:'none',clean(body.institutionName)||null,clean(body.institutionUrl,500)||null,clean(body.publicBio,2000)||null,now,now]);await db.query(`INSERT INTO user_roles (user_id,role) VALUES (?,'contributor')`,[id]);await audit(db,id,'account.registered','user',id,{profession,affiliationType:body.affiliationType||'none'})})}
  catch(error){if(error.code==='ER_DUP_ENTRY')return res.status(409).json({error:'An account already exists for this email.'});throw error}
  res.status(201).json({ok:true,status:'pending',message:'Account submitted for Sanchaya approval.'})
})

app.post('/api/auth/forgot-password',rateLimit('forgot-password',5,60*60*1000),async(req,res)=>{
  if(config.env==='production'&&!emailDeliveryConfigured(config))return res.status(503).json({error:'Password recovery is temporarily unavailable. Please contact Sanchaya.'})
  const userEmail=email(req.body?.email);const rows=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userEmail)?await pool.query('SELECT id,email,preferred_locale FROM users WHERE email=? LIMIT 1',[userEmail]):[]
  let previewUrl
  if(rows.length){const user=rows[0],token=randomToken(32),tokenHash=sha256(token),expires=new Date(Date.now()+config.passwordResetMinutes*60000);const resetUrl=`${config.appOrigin}/?resetToken=${encodeURIComponent(token)}#contribute`
    await transaction(async db=>{await db.query('DELETE FROM password_reset_tokens WHERE user_id=? AND used_at IS NULL',[user.id]);await db.query('INSERT INTO password_reset_tokens (token_hash,user_id,expires_at) VALUES (?,?,?)',[tokenHash,user.id,expires]);await audit(db,user.id,'account.password-reset-requested','user',user.id,{expiresAt:expires.toISOString()})})
    try{const result=await sendPasswordResetEmail({to:user.email,url:resetUrl,locale:user.preferred_locale,config});previewUrl=result.previewUrl}catch(error){await pool.query('DELETE FROM password_reset_tokens WHERE token_hash=?',[tokenHash]);throw error}
  }
  res.json({ok:true,message:'If the email belongs to an account, a password-reset link has been sent.',...(config.env!=='production'&&previewUrl?{previewUrl}:{})})
})

app.post('/api/auth/reset-password',rateLimit('reset-password',8,60*60*1000),async(req,res)=>{
  const token=clean(req.body?.token,500);if(!token)return res.status(400).json({error:'Password-reset link is invalid or expired.'})
  if(typeof req.body?.password!=='string'||req.body.password.length<12||req.body.password.length>200)return res.status(400).json({error:'Password must contain 12–200 characters.'})
  const passwordHash=await hashPassword(req.body.password),tokenHash=sha256(token)
  const changed=await transaction(async db=>{const rows=await db.query('SELECT user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP(3) LIMIT 1 FOR UPDATE',[tokenHash]);if(!rows.length)return false;const userId=rows[0].user_id;await db.query('UPDATE users SET password_hash=? WHERE id=?',[passwordHash,userId]);await db.query('UPDATE password_reset_tokens SET used_at=UTC_TIMESTAMP(3) WHERE token_hash=?',[tokenHash]);await db.query('DELETE FROM sessions WHERE user_id=?',[userId]);await audit(db,userId,'account.password-reset','user',userId,{});return true})
  if(!changed)return res.status(400).json({error:'Password-reset link is invalid or expired.'})
  res.json({ok:true,message:'Password updated. Sign in with the new password.'})
})

app.post('/api/auth/login',rateLimit('login',12,15*60*1000),async(req,res)=>{
  const rows=await pool.query('SELECT * FROM users WHERE email=? LIMIT 1',[email(req.body?.email)]);const user=rows[0]
  if(!user||!await verifyPassword(req.body?.password||'',user.password_hash))return res.status(401).json({error:'Email or password is incorrect.'})
  if(['rejected','suspended'].includes(user.account_status))return res.status(403).json({error:'This account is not available.'})
  const token=randomToken();const expires=new Date(Date.now()+config.sessionDays*86400000)
  await pool.query('INSERT INTO sessions (token_hash,user_id,expires_at,ip_hash,user_agent_hash) VALUES (?,?,?,?,?)',[sha256(token),user.id,expires,sha256(req.ip||''),sha256(req.get('user-agent')||'')])
  res.cookie('kha_session',token,{httpOnly:true,secure:config.env==='production',sameSite:'lax',path:'/',maxAge:config.sessionDays*86400000})
  const roles=await rolesFor(pool,user.id);res.json({user:publicUser(user,roles)})
})
app.post('/api/auth/logout',requireUser,async(req,res)=>{const token=cookies(req).kha_session;if(token)await pool.query('DELETE FROM sessions WHERE token_hash=?',[sha256(token)]);res.clearCookie('kha_session',{path:'/'});res.json({ok:true})})
app.get('/api/auth/me',requireUser,async(req,res)=>{const rows=await pool.query('SELECT COALESCE(SUM(points),0) karma FROM karma_ledger WHERE user_id=?',[req.user.id]);res.json({user:publicUser(req.user,req.roles,rows[0]?.karma)})})
app.put('/api/auth/profile',requireUser,async(req,res)=>{
  const body=req.body||{}
  const displayName=clean(body.displayName,160),displayNameKn=clean(body.displayNameKn,160)||null,profession=clean(body.profession,80)
  const affiliationType=['none','school','college','university','research-institute','museum','government','nonprofit','other'].includes(body.affiliationType)?body.affiliationType:'none'
  if(!displayName||!profession)return res.status(400).json({error:'Name and profession are required.'})
  await pool.query('UPDATE users SET display_name=?,display_name_kn=?,preferred_locale=?,profession=?,profession_details=?,affiliation_type=?,institution_name=?,institution_url=?,public_bio=? WHERE id=?',[displayName,displayNameKn,body.preferredLocale==='en'?'en':'kn',profession,clean(body.professionDetails,255)||null,affiliationType,clean(body.institutionName,255)||null,clean(body.institutionUrl,500)||null,clean(body.publicBio,2000)||null,req.user.id])
  await audit(pool,req.user.id,'account.profile-updated','user',req.user.id,{profession,affiliationType})
  const rows=await pool.query('SELECT COALESCE(SUM(points),0) karma FROM karma_ledger WHERE user_id=?',[req.user.id]);const userRows=await pool.query('SELECT * FROM users WHERE id=? LIMIT 1',[req.user.id])
  res.json({ok:true,user:publicUser(userRows[0],req.roles,rows[0]?.karma)})
})

app.get('/api/administration/dataset',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{
  const current=await latestDataset(pool)
  if(current)return res.json(current)
  const dataset=repositoryDataset();const saved=await insertDatasetRevision(pool,dataset,{revision:1,updatedBy:req.user.id})
  await audit(pool,req.user.id,'dataset.snapshot-seeded','dataset',saved.id,{revision:1,contentSha256:saved.contentSha256})
  res.json({revision:1,schemaVersion:dataset.meta.schemaVersion,contentSha256:saved.contentSha256,dataset,updatedBy:req.user.id,updatedAt:new Date().toISOString()})
})

app.put('/api/administration/dataset',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{
  const dataset=req.body?.dataset;const baseRevision=Number(req.body?.baseRevision||0);if(!dataset||typeof dataset!=='object'||Array.isArray(dataset))return res.status(400).json({error:'A complete atlas dataset object is required.'})
  const issues=datasetIssues(dataset);if(issues.length)return res.status(422).json({error:`Dataset has ${issues.length} validation error(s).`,issues})
  const result=await transaction(async db=>{
    const latest=await latestDataset(db,{lock:true});const currentRevision=Number(latest?.revision||0);if(currentRevision!==baseRevision)throw Object.assign(new Error(`Dataset changed on the server. Reload revision ${currentRevision} before saving.`),{status:409})
    const saved=await insertDatasetRevision(db,dataset,{revision:currentRevision+1,updatedBy:req.user.id});await audit(db,req.user.id,'dataset.snapshot-created','dataset',saved.id,{revision:saved.revision,contentSha256:saved.contentSha256});return saved
  })
  res.status(201).json({ok:true,...result})
})

app.get('/api/administration/release-readiness',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{
  const requiredMigrations=['011_v029_community_operations.sql','012_password_reset.sql','013_portal_messages.sql','014_message_notification_settings.sql']
  const [accounts,contributions,verifications,reviewers,contributors,latest,published,migrations,evidence]=await Promise.all([
    pool.query("SELECT COUNT(*) total FROM users WHERE account_status='pending'"),
    pool.query("SELECT COUNT(*) total FROM contributions WHERE status='submitted'"),
    pool.query("SELECT COUNT(*) total FROM verification_requests WHERE status='pending'"),
    pool.query("SELECT COUNT(DISTINCT ur.user_id) total FROM user_roles ur JOIN users u ON u.id=ur.user_id WHERE ur.role='reviewer' AND u.account_status='approved'"),
    pool.query("SELECT COUNT(DISTINCT ur.user_id) total FROM user_roles ur JOIN users u ON u.id=ur.user_id WHERE ur.role='contributor' AND u.account_status='approved' AND NOT EXISTS (SELECT 1 FROM user_roles reviewer_role WHERE reviewer_role.user_id=ur.user_id AND reviewer_role.role='reviewer')"),
    pool.query('SELECT revision,created_at FROM dataset_snapshots ORDER BY revision DESC LIMIT 1'),
    pool.query('SELECT contribution_count,published_at FROM published_snapshots ORDER BY published_at DESC LIMIT 1'),
    pool.query(`SELECT version FROM schema_migrations WHERE version IN (${requiredMigrations.map(()=>'?').join(',')})`,requiredMigrations),
    pool.query("SELECT COUNT(*) assigned,SUM(status='awaiting-review') awaiting_review,SUM(assignee IS NOT NULL AND assignee<>'' AND reviewer IS NOT NULL AND reviewer<>'' AND assignee<>reviewer) independently_assigned FROM evidence_assignments")
  ])
  const appliedMigrations=new Set(migrations.map(row=>row.version)),communityOperationsReady=appliedMigrations.has(requiredMigrations[0])
  const [campaigns,campaignMembers,imports]=communityOperationsReady?await Promise.all([
    pool.query("SELECT COUNT(*) total FROM research_campaigns WHERE status='active'"),
    pool.query("SELECT COUNT(DISTINCT m.user_id) total FROM research_campaign_members m JOIN research_campaigns c ON c.id=m.campaign_id WHERE c.status='active'"),
    pool.query("SELECT COUNT(*) total FROM research_import_batches WHERE status IN ('submitted','changes-requested')")
  ]):[[{total:0}],[{total:0}],[{total:0}]]
  const revision=Number(latest[0]?.revision||0),reviewerCount=Number(reviewers[0]?.total||0),contributorCount=Number(contributors[0]?.total||0),activeCampaigns=Number(campaigns[0]?.total||0),members=Number(campaignMembers[0]?.total||0),assigned=Number(evidence[0]?.assigned||0),independent=Number(evidence[0]?.independently_assigned||0)
  const checks=[
    {id:'migrations',ready:requiredMigrations.every(version=>appliedMigrations.has(version)),detail:`${requiredMigrations.filter(version=>appliedMigrations.has(version)).length}/${requiredMigrations.length}`},
    {id:'mail',ready:emailDeliveryConfigured(config),detail:emailDeliveryConfigured(config)?'configured':'missing'},
    {id:'reviewers',ready:reviewerCount>=2,detail:String(reviewerCount)},
    {id:'contributors',ready:contributorCount>=3,detail:String(contributorCount)},
    {id:'campaign',ready:activeCampaigns>0&&members>=3,detail:`${activeCampaigns}/${members}`},
    {id:'assignments',ready:assigned>0&&independent>0,detail:`${independent}/${assigned}`},
    {id:'dataset',ready:revision>0,detail:String(revision)}
  ]
  res.json({community:{pendingAccounts:Number(accounts[0]?.total||0),submittedContributions:Number(contributions[0]?.total||0),pendingVerifications:Number(verifications[0]?.total||0),appointedReviewers:reviewerCount,approvedContributors:contributorCount},dataset:{revision,updatedAt:latest[0]?.created_at||null},published:{contributionCount:Number(published[0]?.contribution_count||0),publishedAt:published[0]?.published_at||null},operations:{activeCampaigns,campaignMembers:members,pendingImports:Number(imports[0]?.total||0),evidenceAssignments:assigned,awaitingEvidenceReview:Number(evidence[0]?.awaiting_review||0),independentAssignments:independent},pilot:{version:'0.30',ready:checks.every(check=>check.ready),passed:checks.filter(check=>check.ready).length,total:checks.length,checks,manualChecks:['backup-restore','signup-recovery','approved-static-release']}})
})

app.get('/api/evidence/assignments',requireUser,requireApproved,async(req,res)=>{
  const [rows,historyRows,citationRows]=await Promise.all([
    pool.query('SELECT task_id,status,assignee,reviewer,due_date,review_note,updated_by,updated_at FROM evidence_assignments ORDER BY updated_at DESC'),
    pool.query('SELECT task_id,status,assignee,reviewer,due_date,review_note,updated_by,created_at FROM evidence_assignment_history ORDER BY created_at DESC LIMIT 500'),
    pool.query('SELECT c.id,c.task_id,c.url,c.title,c.locator,c.created_at,u.display_name added_by_name FROM evidence_task_citations c JOIN users u ON u.id=c.added_by ORDER BY c.created_at ASC')
  ])
  const historyByTask=historyRows.reduce((groups,row)=>{const list=groups.get(row.task_id)||[];list.push({status:row.status,assignee:row.assignee||'',reviewer:row.reviewer||'',due:row.due_date?String(row.due_date).slice(0,10):'',reviewNote:row.review_note||'',updatedBy:row.updated_by,updatedAt:row.created_at});groups.set(row.task_id,list);return groups},new Map())
  const citationsByTask=citationRows.reduce((groups,row)=>{const list=groups.get(row.task_id)||[];list.push({id:row.id,url:row.url,title:row.title||'',locator:row.locator||'',addedBy:row.added_by_name,addedAt:row.created_at});groups.set(row.task_id,list);return groups},new Map())
  const taskIds=new Set([...rows.map(row=>row.task_id),...citationsByTask.keys()])
  res.json({assignments:[...taskIds].map(taskId=>{const row=rows.find(item=>item.task_id===taskId);return {taskId,status:row?.status||'todo',assignee:row?.assignee||'',reviewer:row?.reviewer||'',due:row?.due_date?String(row.due_date).slice(0,10):'',reviewNote:row?.review_note||'',history:historyByTask.get(taskId)||[],citations:citationsByTask.get(taskId)||[],updatedBy:row?.updated_by||null,updatedAt:row?.updated_at||null}})})
})

app.post('/api/evidence/assignments/:taskId/citations',requireUser,requireApproved,async(req,res)=>{
  const taskId=clean(req.params.taskId,240)
  if(!taskId||!/^[^/]+$/.test(taskId))return res.status(400).json({error:'A valid evidence task ID is required.'})
  const [citation]=normalizeCitationList([req.body||{}],1)
  if(!citation)return res.status(400).json({error:'A valid HTTP(S) citation URL is required.'})
  const id=randomUUID()
  await transaction(async db=>{await db.query(`INSERT INTO evidence_assignments (task_id,status,updated_by) VALUES (?,'todo',?) ON DUPLICATE KEY UPDATE task_id=VALUES(task_id)`,[taskId,req.user.id]);await db.query(`INSERT INTO evidence_task_citations (id,task_id,url,title,locator,added_by) VALUES (?,?,?,?,?,?)`,[id,taskId,citation.url,citation.title||null,citation.locator||null,req.user.id]);await audit(db,req.user.id,'evidence-citation.added','evidence-task',taskId,{citationId:id,url:citation.url})})
  res.status(201).json({ok:true,citation:{id,url:citation.url,title:citation.title||'',locator:citation.locator||'',addedBy:req.user.display_name,addedAt:new Date().toISOString()}})
})

app.put('/api/evidence/assignments/:taskId',requireUser,requireApproved,async(req,res)=>{
  const taskId=clean(req.params.taskId,240);const status=req.body?.status;const assignee=clean(req.body?.assignee,255)||null;const reviewer=clean(req.body?.reviewer,255)||null;const due=clean(req.body?.due,10)||null;const reviewNote=clean(req.body?.reviewNote,10000)||null
  if(!taskId||!/^[^/]+$/.test(taskId))return res.status(400).json({error:'A valid evidence task ID is required.'})
  if(!['todo','in-progress','awaiting-review','blocked','complete'].includes(status))return res.status(400).json({error:'Evidence task status is invalid.'})
  if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))return res.status(400).json({error:'Due date must use YYYY-MM-DD.'})
  if(status==='complete'&&!reviewer)return res.status(400).json({error:'A named independent reviewer is required before a task can be marked complete.'})
  if(status==='complete'&&assignee&&reviewer&&assignee.toLowerCase()===reviewer.toLowerCase())return res.status(400).json({error:'The assignee and independent reviewer must be different.'})
  if(['awaiting-review','complete'].includes(status)){const [{total}={total:0}]=await pool.query('SELECT COUNT(*) total FROM evidence_task_citations WHERE task_id=?',[taskId]);if(!Number(total))return res.status(422).json({error:'At least one source citation must be attached before this task can move to review or completion.'})}
  await transaction(async db=>{await db.query(`INSERT INTO evidence_assignments (task_id,status,assignee,reviewer,due_date,review_note,updated_by) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),assignee=VALUES(assignee),reviewer=VALUES(reviewer),due_date=VALUES(due_date),review_note=VALUES(review_note),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP(3)`,[taskId,status,assignee,reviewer,due,reviewNote,req.user.id]);await db.query(`INSERT INTO evidence_assignment_history (id,task_id,status,assignee,reviewer,due_date,review_note,updated_by) VALUES (?,?,?,?,?,?,?,?)`,[randomUUID(),taskId,status,assignee,reviewer,due,reviewNote,req.user.id]);await audit(db,req.user.id,'evidence-assignment.updated','evidence-task',taskId,{status,assignee,reviewer,due,hasReviewNote:Boolean(reviewNote)})})
  res.json({ok:true,taskId,status,assignee:assignee||'',reviewer:reviewer||'',due:due||'',reviewNote:reviewNote||''})
})

