app.post('/api/research-imports',requireUser,requireApproved,async(req,res)=>{const format=['csv','kml'].includes(req.body?.format)?req.body.format:null,fileName=clean(req.body?.fileName,255),recordType=clean(req.body?.recordType,80),rows=normalizeImportRows(req.body?.rows);if(!format||!fileName||!recordType||!rows.length)return res.status(400).json({error:'A CSV/KML file, record type and at least one parsed row are required.'});if((req.body?.rows||[]).length>500)return res.status(413).json({error:'A staging batch is limited to 500 rows.'});const id=randomUUID();await pool.query(`INSERT INTO research_import_batches (id,submitted_by,file_name,import_format,record_type,row_count,payload_json,status) VALUES (?,?,?,?,?,?,?,'submitted')`,[id,req.user.id,fileName,format,recordType,rows.length,JSON.stringify(rows)]);await audit(pool,req.user.id,'research-import.submitted','research-import',id,{format,recordType,rowCount:rows.length});res.status(201).json({ok:true,id,status:'submitted',rowCount:rows.length})})
app.get('/api/administration/research-imports',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{const rows=await pool.query(`SELECT b.*,u.display_name contributor_name FROM research_import_batches b JOIN users u ON u.id=b.submitted_by WHERE b.status IN ('submitted','changes-requested') ORDER BY b.created_at ASC LIMIT 100`);res.json({batches:rows.map(row=>({...row,payload:safeJson(row.payload_json)||[]}))})})
app.post('/api/administration/research-imports/:id/decision',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{const status=req.body?.decision==='approve'?'approved':req.body?.decision==='request-changes'?'changes-requested':req.body?.decision==='reject'?'rejected':null,note=clean(req.body?.note,10000);if(!status||!note)return res.status(400).json({error:'A decision and reviewer note are required.'});const batch=(await pool.query(`SELECT * FROM research_import_batches WHERE id=? AND status IN ('submitted','changes-requested') LIMIT 1`,[clean(req.params.id,36)]))[0];if(!batch)return res.status(409).json({error:'Import batch is no longer awaiting review.'});await pool.query('UPDATE research_import_batches SET status=?,reviewer_note=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP(3) WHERE id=?',[status,note,req.user.id,batch.id]);await notify(pool,batch.submitted_by,'import','Research import reviewed','ಸಂಶೋಧನಾ ಆಮದು ಪರಿಶೀಲಿಸಲಾಗಿದೆ',`Your ${batch.import_format.toUpperCase()} batch is ${status}.`,`${batch.import_format.toUpperCase()} ಕಡತದ ಸ್ಥಿತಿ: ${status}.`,'research-import',batch.id);await audit(pool,req.user.id,`research-import.${status}`,'research-import',batch.id,{rowCount:batch.row_count});res.json({ok:true,status})})

app.get('/api/collaboration-proposals/mine',requireUser,requireApproved,async(req,res)=>{const rows=await pool.query('SELECT id,entity_kind,organization_name,collaboration_type,scope_en,scope_kn,status,reviewer_note,reviewed_at,created_at FROM collaboration_proposals WHERE proposer_user_id=? ORDER BY created_at DESC',[req.user.id]);res.json({proposals:rows})})
app.get('/api/administration/collaboration-proposals',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{const rows=await pool.query(`SELECT p.*,u.display_name proposer_name,u.institution_name proposer_institution FROM collaboration_proposals p JOIN users u ON u.id=p.proposer_user_id WHERE p.status IN ('submitted','under-review','changes-requested') ORDER BY p.created_at ASC LIMIT 100`);res.json({proposals:rows})})
app.post('/api/administration/collaboration-proposals/:id/decision',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{const decision=req.body?.decision,status=decision==='approve'?'approved':decision==='request-changes'?'changes-requested':decision==='decline'?'declined':null,note=clean(req.body?.note,10000);if(!status||!note)return res.status(400).json({error:'A decision and reviewer note are required.'});const result=await pool.query(`UPDATE collaboration_proposals SET status=?,reviewer_user_id=?,reviewer_note=?,reviewed_at=UTC_TIMESTAMP(3) WHERE id=? AND status IN ('submitted','under-review','changes-requested')`,[status,req.user.id,note,req.params.id]);if(!result.affectedRows)return res.status(409).json({error:'Proposal is no longer awaiting review.'});await audit(pool,req.user.id,`collaboration.${status}`,'collaboration-proposal',req.params.id,{decision});res.json({ok:true,status})})

app.get('/api/reviews/queue',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{const rows=await pool.query(`SELECT c.*,u.display_name contributor_name,u.verified_badge FROM contributions c JOIN users u ON u.id=c.contributor_id WHERE c.status='submitted' AND c.contributor_id<>? ORDER BY c.submitted_at ASC LIMIT 100`,[req.user.id]);res.json({contributions:rows.map(row=>({...row,proposed_record_json:safeJson(row.proposed_record_json),citations_json:safeJson(row.citations_json)}))})})
app.post('/api/reviews/:contributionId',requireUser,requireApproved,requireRole('reviewer','administrator'),async(req,res)=>{
  const decision=req.body?.decision;const publicComment=clean(req.body?.publicComment,10000);if(!['approve','request-changes','reject'].includes(decision)||!publicComment)return res.status(400).json({error:'A decision and public review comment are required.'})
  const outcome=await transaction(async db=>{const rows=await db.query('SELECT * FROM contributions WHERE id=? FOR UPDATE',[req.params.contributionId]);const contribution=rows[0];if(!contribution||contribution.status!=='submitted')throw Object.assign(new Error('Contribution is no longer awaiting review.'),{status:409});if(contribution.contributor_id===req.user.id)throw Object.assign(new Error('Reviewers cannot decide their own contributions.'),{status:403});const normalizedContribution={...contribution,record:safeJson(contribution.proposed_record_json)};const assessment=normalizeTranslationAssessment(req.body?.assessment);const approvalIssues=translationApprovalIssues({decision,contribution:normalizedContribution,assessment});if(approvalIssues.length)throw Object.assign(new Error(approvalIssues.join(' ')),{status:422});const reviewId=randomUUID();await db.query(`INSERT INTO contribution_reviews (id,contribution_id,reviewer_id,contribution_version,decision,language_code,review_scope,public_comment,private_note,assessment_json) VALUES (?,?,?,?,?,?,?,?,?,?)`,[reviewId,contribution.id,req.user.id,contribution.version,decision,assessment.languageCode||null,assessment.reviewScope||null,publicComment,clean(req.body?.privateNote,10000)||null,contribution.action==='translation'?JSON.stringify(assessment):null]);const status=decision==='approve'?'approved':decision==='request-changes'?'changes-requested':'rejected';await db.query('UPDATE contributions SET status=?,decided_at=UTC_TIMESTAMP(3) WHERE id=?',[status,contribution.id]);if(decision==='approve'){const citations=safeJson(contribution.citations_json)||[];const contributorPoints=20+Math.min(citations.length,5)*2;await db.query(`INSERT INTO karma_ledger (id,user_id,contribution_id,points,reason,note,created_by) VALUES (?,?,?,?,?,?,?)`,[randomUUID(),contribution.contributor_id,contribution.id,contributorPoints,'approved-contribution',`Approved contribution with ${citations.length} citation(s).`,req.user.id]);await db.query(`INSERT INTO karma_ledger (id,user_id,review_id,points,reason,note,created_by) VALUES (?,?,?,?,?,?,?)`,[randomUUID(),req.user.id,reviewId,5,'approved-review','Completed an approval review.',req.user.id])}await notify(db,contribution.contributor_id,'review','Contribution review completed','ಕೊಡುಗೆ ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಂಡಿದೆ',`Your contribution “${contribution.title}” is ${status}. ${publicComment}`,`“${contribution.title}” ಕೊಡುಗೆಯ ಸ್ಥಿತಿ: ${status}. ${publicComment}`,'contribution',contribution.id);await audit(db,req.user.id,`contribution.${status}`,'contribution',contribution.id,{reviewId,decision,reviewScope:assessment.reviewScope||null,languageCode:assessment.languageCode||null});return {status,reviewId}});res.json({ok:true,...outcome})
})

app.get('/api/community/leaderboard',async(req,res)=>{const rows=await pool.query(`SELECT u.id,u.display_name,u.display_name_kn,u.profession,u.institution_name,u.verified_badge,COALESCE(SUM(k.points),0) karma FROM users u LEFT JOIN karma_ledger k ON k.user_id=u.id WHERE u.account_status='approved' GROUP BY u.id ORDER BY karma DESC,u.display_name ASC LIMIT 100`);res.json({people:rows.map(row=>({...row,verified_badge:Boolean(row.verified_badge),karma:Number(row.karma)}))})})

app.get('/api/administration/users',requireUser,requireRole('administrator'),async(req,res)=>{const rows=await pool.query(`SELECT u.id,u.email,u.display_name,u.display_name_kn,u.profession,u.affiliation_type,u.institution_name,u.account_status,u.verified_badge,u.created_at,COALESCE(GROUP_CONCAT(r.role),'') roles FROM users u LEFT JOIN user_roles r ON r.user_id=u.id GROUP BY u.id ORDER BY FIELD(u.account_status,'pending','approved','suspended','rejected'),u.created_at`);res.json({users:rows})})
app.get('/api/administration/messages',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{const status=['new','triaged','in-progress','replied','closed','spam'].includes(req.query.status)?req.query.status:'new',category=['question','correction','source','technical','collaboration','other'].includes(req.query.category)?req.query.category:null,params=[status];let where='m.status=?';if(category){where+=' AND m.category=?';params.push(category)}const rows=await pool.query(`SELECT m.*,u.display_name account_name,a.display_name assignee_name FROM portal_messages m LEFT JOIN users u ON u.id=m.user_id LEFT JOIN users a ON a.id=m.assigned_to WHERE ${where} ORDER BY m.created_at DESC LIMIT 200`,params);res.json({messages:rows})})
app.patch('/api/administration/messages/:id',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{const status=['new','triaged','in-progress','replied','closed','spam'].includes(req.body?.status)?req.body.status:null;if(!status)return res.status(400).json({error:'A supported message status is required.'});const result=await pool.query(`UPDATE portal_messages SET status=?,assigned_to=IF(?, ?, assigned_to),admin_note=?,closed_at=IF(? IN ('closed','spam'),UTC_TIMESTAMP(3),NULL) WHERE id=?`,[status,req.body?.assignToMe===true,req.user.id,clean(req.body?.adminNote,10000)||null,status,clean(req.params.id,36)]);if(!result.affectedRows)return res.status(404).json({error:'Message not found.'});await audit(pool,req.user.id,'portal-message.updated','portal-message',req.params.id,{status});res.json({ok:true,status})})
app.get('/api/administration/notification-settings',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>res.json({providers:await notificationSettingsSummary(pool,config)}))
app.put('/api/administration/notification-settings/:provider',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{const provider=clean(req.params.provider,32);const settings=await saveNotificationSettings(pool,config,provider,req.body||{},req.user.id);await audit(pool,req.user.id,'notification-settings.updated','notification-provider',provider,{enabled:settings.enabled});res.json({ok:true,settings})})
app.post('/api/administration/notification-settings/:provider/test',requireUser,requireApproved,requireRole('administrator'),async(req,res)=>{const provider=clean(req.params.provider,32);if(!['telegram','whatsapp'].includes(provider))return res.status(400).json({error:'Unsupported notification provider.'});await sendPortalNotifications(`Karnataka Historical Atlas\n${provider} integration test\n${config.appOrigin}/#admin`,pool,config,fetch,provider);res.json({ok:true})})
app.patch('/api/administration/users/:id',requireUser,requireRole('administrator'),async(req,res)=>{const status=req.body?.accountStatus;if(!['approved','rejected','suspended'].includes(status))return res.status(400).json({error:'Account decision is invalid.'});if(req.params.id===req.user.id&&status!=='approved')return res.status(400).json({error:'Administrators cannot suspend or reject their own account.'});await transaction(async db=>{const target=(await db.query('SELECT id FROM users WHERE id=? LIMIT 1 FOR UPDATE',[req.params.id]))[0];if(!target)throw Object.assign(new Error('Account not found.'),{status:404});await db.query("UPDATE users SET account_status=?,approved_by=?,approved_at=IF(?='approved',UTC_TIMESTAMP(3),approved_at),rejection_reason=? WHERE id=?",[status,req.user.id,status,clean(req.body?.reason,500)||null,target.id]);for(const role of (Array.isArray(req.body?.roles)?req.body.roles:[]).filter(role=>['reviewer','verification-officer','exporter','administrator'].includes(role)))await db.query('INSERT IGNORE INTO user_roles (user_id,role,appointed_by) VALUES (?,?,?)',[target.id,role,req.user.id]);await notify(db,target.id,'account','Account status updated','ಖಾತೆ ಸ್ಥಿತಿ ನವೀಕರಿಸಲಾಗಿದೆ',`Your Sanchaya account is ${status}.`,`ನಿಮ್ಮ ಸಂಚಯ ಖಾತೆಯ ಸ್ಥಿತಿ: ${status}.`,'user',target.id);await audit(db,req.user.id,`account.${status}`,'user',target.id,{roles:req.body?.roles||[]})});res.json({ok:true,status})})
app.get('/api/administration/verifications',requireUser,requireRole('verification-officer','administrator'),async(req,res)=>{const rows=await pool.query(`SELECT v.id,v.user_id,v.institution_name,v.institutional_identifier,v.document_mime,v.document_size,v.status,v.created_at,u.display_name,u.email FROM verification_requests v JOIN users u ON u.id=v.user_id WHERE v.status='pending' ORDER BY v.created_at`);res.json({requests:rows})})
app.get('/api/administration/verifications/:id/document',requireUser,requireRole('verification-officer','administrator'),async(req,res)=>{const row=(await pool.query('SELECT * FROM verification_requests WHERE id=? LIMIT 1',[req.params.id]))[0];if(!row)return res.status(404).json({error:'Verification request not found.'});if(!row.document_storage_key)return res.status(410).json({error:'This private document has been deleted under the retention policy.'});const encrypted=await readFile(path.join(config.uploadDir,row.document_storage_key));res.type(row.document_mime).set('Cache-Control','no-store').send(decryptDocument(encrypted,config.documentEncryptionKey))})
app.post('/api/administration/verifications/:id/decision',requireUser,requireRole('verification-officer','administrator'),async(req,res)=>{const status=req.body?.decision==='approve'?'approved':req.body?.decision==='reject'?'rejected':null;if(!status)return res.status(400).json({error:'Verification decision is invalid.'});await transaction(async db=>{const row=(await db.query('SELECT * FROM verification_requests WHERE id=? FOR UPDATE',[req.params.id]))[0];if(!row||row.status!=='pending')throw Object.assign(new Error('Request is no longer pending.'),{status:409});await db.query('UPDATE verification_requests SET status=?,review_note=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP(3),delete_after=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 30 DAY) WHERE id=?',[status,clean(req.body?.note,1000)||null,req.user.id,row.id]);if(status==='approved')await db.query('UPDATE users SET verified_badge=1 WHERE id=?',[row.user_id]);await audit(db,req.user.id,`verification.${status}`,'verification-request',row.id,{userId:row.user_id})});res.json({ok:true,status})})

app.post('/api/administration/certificates',requireUser,requireRole('administrator'),async(req,res)=>{const userId=clean(req.body?.userId,36);const from=clean(req.body?.periodFrom,10);const to=clean(req.body?.periodTo,10);if(!userId||!/^\d{4}-\d{2}-\d{2}$/.test(from)||!/^\d{4}-\d{2}-\d{2}$/.test(to))return res.status(400).json({error:'User and certificate period are required.'});const totals=await pool.query(`SELECT COALESCE(SUM(CASE WHEN reason IN ('approved-contribution','citation-quality') THEN points ELSE 0 END),0) contribution_points,COALESCE(SUM(CASE WHEN reason IN ('approved-review','verification-service') THEN points ELSE 0 END),0) reviewer_points FROM karma_ledger WHERE user_id=? AND DATE(created_at) BETWEEN ? AND ?`,[userId,from,to]);const id=randomUUID(),code=randomToken(18).slice(0,32);await pool.query(`INSERT INTO certificates (id,verification_code,user_id,title_en,title_kn,period_from,period_to,contribution_points,reviewer_points,statement_en,statement_kn,issued_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,[id,code,userId,clean(req.body?.titleEn,255)||'Certificate of contribution',clean(req.body?.titleKn,255)||'ಕೊಡುಗೆ ಪ್ರಮಾಣಪತ್ರ',from,to,totals[0].contribution_points,totals[0].reviewer_points,clean(req.body?.statementEn,3000)||'For contributions to Kannada language technology and the Karnataka Historical Atlas.',clean(req.body?.statementKn,3000)||'ಕನ್ನಡ ಭಾಷಾ ತಂತ್ರಜ್ಞಾನ ಮತ್ತು ಕರ್ನಾಟಕ ಇತಿಹಾಸ ಭೂಪಟಕ್ಕೆ ನೀಡಿದ ಕೊಡುಗೆಗಾಗಿ.',req.user.id]);await audit(pool,req.user.id,'certificate.issued','certificate',id,{userId,code});res.status(201).json({ok:true,id,verificationCode:code})})
app.get('/api/certificates/mine',requireUser,async(req,res)=>{const rows=await pool.query('SELECT * FROM certificates WHERE user_id=? ORDER BY issued_at DESC',[req.user.id]);res.json({certificates:rows})})
app.get('/api/certificates/verify/:code',async(req,res)=>{const rows=await pool.query(`SELECT c.verification_code,c.title_en,c.title_kn,c.period_from,c.period_to,c.contribution_points,c.reviewer_points,c.statement_en,c.statement_kn,c.issued_at,c.revoked_at,u.display_name,u.display_name_kn FROM certificates c JOIN users u ON u.id=c.user_id WHERE c.verification_code=? LIMIT 1`,[req.params.code]);if(!rows.length)return res.status(404).json({error:'Certificate not found.'});res.json({certificate:rows[0],valid:!rows[0].revoked_at})})

app.use('/api',(req,res)=>res.status(404).json({error:'API route not found.'}))
if(existsSync(config.publicDir)){app.use(express.static(config.publicDir,{index:false,maxAge:config.env==='production'?'1h':0}));app.use((req,res,next)=>{if(req.method!=='GET')return next();res.sendFile(path.join(config.publicDir,'index.html'))})}
app.use((error,req,res,next)=>{console.error(error);if(res.headersSent)return next(error);res.status(error.status||500).json({error:error.status?error.message:'The service could not complete this request.'})})

const server=app.listen(config.port,()=>console.log(`Karnataka Historical Atlas community service listening on ${config.port}`))
const shutdown=async()=>{server.close();await closeDatabase()}
process.on('SIGINT',shutdown);process.on('SIGTERM',shutdown)

export { app }
